            const rank = SafeGetValue(data, 'user.品级', '未知');
            document.getElementById('user-status').innerText = `职位: ${job} | 品级: ${rank}`;

            const location = SafeGetValue(data, 'user.详细所在地', '未知');
            document.getElementById('location-details').innerText = `所处: ${location}`;

            const shichen = SafeGetValue(data, '世界.当前时辰', '未知');
            const modernTime = convertShichen(shichen);
            document.getElementById('time-details').innerText = `时辰: ${shichen} (${modernTime})`;

            updateCharacterCard('luoyun', data.洛云);
            updateCharacterCard('yinsuwen', data.殷素问);

        } catch (error) {
            console.error("状态栏加载出错:", error);
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
